typedef long long LL;
typedef long double LD;

int cond = 1;

double solve() {
  double d;
  int n;
  cin >> d >> n;
  double tmax = 0.;
  for (int i = 0; i < n; ++i) {
    double k, s;
    cin >> k >> s;
    if (k < d) {
      double t = (double)(d - k) / s;
      tmax = t > tmax ? t : tmax;
    }
  }
  return d / tmax;
}

int main() {
  int t;
  cin >> t;
  for (int x = 1; x <= t; ++x) {

    cout.precision(9);
    cout << "Case #" << x << ": " << fixed << solve() << endl; // result
  }
  return 0;
}
