      if (temp <= s.substr(i + 1))
        continue;
      res[i]--;
      for (int(j) = (i + 1); (j) < (s.size()); (j)++)
        res[j] = '9';
      break;
    }
    while (res[0] == '0')
      res = res.substr(1);
    cout << res << endl;
  }
}
