    if (p[2].first > n / 2) {
      cout << "IMPOSSIBLE" << endl;
    } else {
      string ans;
      for (int i = 0; i < n; i++)
        ans.push_back(' ');

      for (int c = 2; c >= 0; c--) {
        if (c % 2 == 0) {
          for (int i = 0; i < n; i++) {
            if (p[c].first == 0)
              break;

            int prev = (i - 1 + n) % n;
            if (ans[prev] != p[c].second && ans[i] == ' ') {
              ans[i] = p[c].second;
              p[c].first--;
            }
          }
        } else {
          for (int i = n - 1; i >= 0; i--) {
            if (p[c].first == 0)
              break;

            int next = (i + 1 + n) % n;
            if (ans[next] != p[c].second && ans[i] == ' ') {
              ans[i] = p[c].second;
              p[c].first--;
            }
          }
        }
      }
      for (int i = 0; i < n; i++)
        if (ans[i] == ' ')
          cerr << "BUG" << endl;

      cout << ans << endl;
    }
  }
  return 0;
}
